import{_ as t,o,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"根据条件调用 Composable 的最佳实践","description":"1. 背景和问题 在 Vue 3 中，composable 是封装状态逻辑的强大工具，但当需要根据条件（如 props.visible）调用时，可能导致性能浪费或响应式问题。例如，在金融交易系统的 sltp field.vue 中，仅当 props.visible true 时调。","frontmatter":{"title":"根据条件调用 Composable 的最佳实践","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"1. 背景和问题 在 Vue 3 中，composable 是封装状态逻辑的强大工具，但当需要根据条件（如 props.visible）调用时，可能导致性能浪费或响应式问题。例如，在金融交易系统的 sltp field.vue 中，仅当 props.visible true 时调。","sidebarWeight":6,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/composable/根据条件调用 Composable 的最佳实践.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/根据条件调用 Composable 的最佳实践.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/根据条件调用 Composable 的最佳实践.md"}'),n={name:"posts/Vue系统教程/03-响应式与组合式 API/根据条件调用 Composable 的最佳实践.md"};function l(i,e,p,a,f,c){return o(),s("div",null,[...e[0]||(e[0]=[r('<div><h1 id="根据条件调用-composable-的最佳实践" tabindex="-1">根据条件调用 Composable 的最佳实践 <a class="header-anchor" href="#根据条件调用-composable-的最佳实践" aria-label="Permalink to &quot;根据条件调用 Composable 的最佳实践&quot;">​</a></h1><blockquote><p>本节目标：理解“根据条件调用 Composable 的最佳实践”的核心思路，并能把它用于实际开发或面试表达。 <strong>1. 背景和问题</strong> 在 Vue 3 中，composable 是封装状态逻辑的强大工具，但当需要根据条件（如 props.visible）调用时，可能导致性能浪费或响应式问题。例如，在金融交易系统的 sltp-field.vue 中，仅当 props.visible = true 时调用 useSLTP： const { difference, meta } = useSLTP(toRef(props, &#39;config&#39;), props.isStopLoss); <strong>问题</strong>：</p></blockquote><ul><li>无条件调用导致隐藏组件时的计算浪费。</li><li>条件调用可能丢失响应式。</li><li>TypeScript 类型安全需保证。</li></ul><p><strong>2. 解决方案</strong><strong>方法 1：使用 computed 包装</strong> const defaultMeta: FieldMeta = { min: -Number.MAX_VALUE, max: Number.MAX_VALUE, step: 1, precision: 2 };const defaultDifference: DifferenceMetrics | null = null; const sltpData = computed(() =&gt; { if (!props.visible) { return { difference: ref(defaultDifference), meta: ref(defaultMeta) }; } return useSLTP(toRef(props, &#39;config&#39;), props.isStopLoss);}); const { difference, meta } = sltpData.value; <strong>优点</strong>：简洁、响应式、性能优。 <strong>适用</strong>：纯数据、无副作用的 composable。 <strong>方法 2：使用 watch 控制</strong> const difference = ref&lt;DifferenceMetrics | null&gt;(defaultDifference);const meta = ref&lt;FieldMeta&gt;(defaultMeta); watch( () =&gt; props.visible, (visible) =&gt; { if (visible) { const { difference: newDifference, meta: newMeta } = useSLTP(toRef(props, &#39;config&#39;), props.isStopLoss); difference.value = newDifference.value; meta.value = newMeta.value; } }, { immediate: true }); <strong>优点</strong>：灵活，支持副作用。 <strong>适用</strong>：有定时器、事件监听的 composable。 <strong>方法 3：使用 ref 手动触发</strong> const sltpInstance = ref(null); watchEffect(() =&gt; { if (props.visible) { sltpInstance.value = useSLTP(toRef(props, &#39;config&#39;), props.isStopLoss); } else { sltpInstance.value = null; }}); const difference = computed(() =&gt; sltpInstance.value ? sltpInstance.value.difference.value : defaultDifference); <strong>优点</strong>：精确控制，适合资源管理。 <strong>适用</strong>：需销毁或重用的 composable。 <strong>3. 最佳实践</strong></p><ol><li><strong>优先</strong> computed：适合简单条件，保持响应式。</li><li><strong>默认值</strong>：提供类型安全默认值（如 defaultMeta）。</li><li><strong>响应式</strong>：用 ref 包装默认值。</li><li><strong>边界处理</strong>：UI 显示占位符（如 -）。</li><li><strong>日志</strong>：记录无效参数警告。</li><li><strong>性能</strong>：监控 composable 开销。</li><li><strong>测试</strong>：验证条件切换和边界条件。</li></ol><p><strong>4. 示例：sltp-field.vue</strong> const sltpData = computed(() =&gt; { if (!props.visible) { return { difference: ref(defaultDifference), meta: ref(defaultMeta) }; } return useSLTP(toRef(props, &#39;config&#39;), props.isStopLoss);}); <strong>效果</strong>：仅 visible = true 时计算，符合金融系统性能要求。 <strong>5. 常见问题</strong><strong>Q1：副作用如何处理？</strong></p><ul><li>使用 watch，在 onUnmounted 清理。</li></ul><p><strong>Q2：多条件如何组合？</strong></p><ul><li>在 computed 中检查多个条件。</li></ul><p><strong>6. 总结</strong> computed 是条件调用 composable 的首选，结合默认值和边界处理，确保性能和鲁棒性。在金融系统中，优化计算和用户体验至关重要。</p></div>',1)])])}const d=t(n,[["render",l]]);export{g as __pageData,d as default};
